# 3.实现投影的代码实现
![S5](https://cdn.jsdelivr.net/gh/Xn0O/nnoo@main/assets/blog/p1/S5.webp)
完整代码：
```HLSL
Shader "L0/L07/LightShadow" {                 //路径名

    Properties {                        //unity里inspector的参数

    }


    SubShader {
        Tags {
            "RenderType"="Opaque"
        }
        Pass {
            Name "FORWARD"
            Tags {
                "LightMode"="ForwardBase"
            }
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"
            //#include "UnityPBSLighting.cginc"     //PBR的东西，删了
            //#include "UnityStandardBRDF.cginc"
            #include "AutoLight.cginc"  //unity投影必须有这个库
            #include "Lighting.cginc"   //同上

            #pragma multi_compile_fwdbase_fullshadows
            #pragma target 3.0




            //声明参数


            struct VertexInput {                                    //输入结构
                float4 vertex : POSITION;

            };


            struct VertexOutput {                                   //输出结构
                float4 pos : SV_POSITION;                         //裁切空间，可以先理解为屏幕空间
                LIGHTING_COORDS(0,1)                                //投影坐标，Unity已经封装的，格式有点奇怪，如果占用了COORD0那么就填（1，2）
            };

            //输入》顶点Shader》输出
            VertexOutput vert (VertexInput v) {                     //顶点Shader
                VertexOutput o = (VertexOutput)0;
